import Foundation

/// Decides which pasteboard changes are worth recording.
public struct CapturePolicy: Sendable {
    /// Pasteboard types that password managers and similar apps use to mark content clipboard
    /// managers should leave alone. See http://nspasteboard.org.
    public static let privateTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
        "PasswordPboardType",
        "net.antelle.keeweb",
    ]

    /// Clippings larger than this (in UTF-8 bytes) are skipped to keep memory use predictable.
    public static let maxBytes = 2 * 1024 * 1024

    public var ignoredBundleIDs: Set<String>
    public var ignoresWhitespaceOnly: Bool

    public init(ignoredBundleIDs: Set<String> = [], ignoresWhitespaceOnly: Bool = true) {
        self.ignoredBundleIDs = ignoredBundleIDs
        self.ignoresWhitespaceOnly = ignoresWhitespaceOnly
    }

    /// Checked before reading any content, so private data is never even loaded.
    public func allowsContent(types: [String], sourceBundleID: String?) -> Bool {
        if let sourceBundleID, ignoredBundleIDs.contains(sourceBundleID) {
            return false
        }
        return !types.contains(where: Self.privateTypes.contains)
    }

    public func accepts(_ text: String) -> Bool {
        if text.isEmpty || text.utf8.count > Self.maxBytes {
            return false
        }
        if ignoresWhitespaceOnly && text.allSatisfy(\.isWhitespace) {
            return false
        }
        return true
    }
}
